/** Real PostgreSQL and SDK/HTTP protocol tests. The S3 service is a loopback double,
 * not a live cloud account; this report cannot satisfy the live-provider gate. */
import assert from "node:assert/strict";
import { createHash, randomUUID } from "node:crypto";
import { readFileSync, writeFileSync } from "node:fs";
import { eq, inArray } from "drizzle-orm";
import { startS3MultipartEmulator } from "./helpers/s3-multipart-emulator.mjs";
const { url } = JSON.parse(readFileSync(".data/qa-database.json", "utf8")) as {url: string};
if (new URL(url).hostname !== "127.0.0.1" || new URL(url).pathname !== "/maras_qa" || process.env.DATABASE_URL && process.env.DATABASE_URL !== url) throw new Error("Dedicated local QA database required");
if (process.env.S3_BUCKET || process.env.S3_ENDPOINT || process.env.GEMINI_API_KEY || process.env.RESEND_API_KEY || process.env.TAP_SECRET_KEY) throw new Error("Do not supply live provider credentials");
const s3 = await startS3MultipartEmulator();
Object.assign(process.env, { DATABASE_URL: url, DATABASE_SSL: "false", S3_ENDPOINT: s3.endpoint, S3_BUCKET: s3.bucket,
  S3_ACCESS_KEY_ID: s3.accessKey, S3_SECRET_ACCESS_KEY: s3.secretKey, S3_ALLOW_INSECURE_LOOPBACK: "true", S3_FORCE_PATH_STYLE: "true", NODE_ENV: "test", S3_MULTIPART_ENABLED: "true" });
const originalFetch = globalThis.fetch;
globalThis.fetch = async (input, options) => {
  const target = new URL(input instanceof Request ? input.url : String(input));
  if (target.hostname !== "127.0.0.1") throw new Error("External network forbidden in resumable QA");
  return originalFetch(input, options);
};
const { getDb, getPool, closeDb } = await import("../db/index");
const { users, videoUploadSessions, storageCleanupJobs, videoAssets, videoProcessingJobs } = await import("../db/schema");
const service = await import("../lib/video-upload-sessions");
const transport = await import("../lib/railway-direct-upload");
const { runStorageCleanupBatch } = await import("../lib/storage-cleanup");
const { VIDEO_PART_BYTES, validateVideoManifest } = await import("../lib/video-upload-policy");
const db = getDb(), prefix = `qa-resume-${randomUUID()}`, owners: number[] = [], checks: string[] = [];
const pass = (message: string) => { checks.push(message); console.log("PASS", message); };
const checksum = (body: Uint8Array) => createHash("sha256").update(body).digest("base64");
function input(body: Buffer, requestId = randomUUID()) { return { clientRequestId: requestId, courseSlug: prefix, lessonId: "lesson", contentType: "video/mp4", sizeBytes: body.length,
  checksums: Array.from({length: Math.ceil(body.length / VIDEO_PART_BYTES)}, (_, index) => checksum(body.subarray(index * VIDEO_PART_BYTES, (index+1)*VIDEO_PART_BYTES))) }; }
async function put(owner: number, id: string, number: number, body: Buffer) {
  const signed = await service.signVideoUploadPart(owner, id, number);
  const result = await fetch(signed.uploadUrl, {method: "PUT", headers: signed.headers, body: new Uint8Array(body)});
  assert.equal(result.status, 200, await result.text()); return signed;
}
async function expectCode(work: Promise<unknown>, code: number) { await assert.rejects(work, (error: unknown) => error instanceof service.VideoUploadError && error.status === code); }
try {
  for (let n = 0; n < 2; n++) { const [owner] = await db.insert(users).values({ email: `${prefix}-${n}@example.test`, fullName: "Synthetic upload owner", passwordHash: "not-a-login-hash", role: "supervisor" }).returning({id: users.id}); owners.push(owner.id); }
  const [owner, other] = owners;
  const body = Buffer.alloc(VIDEO_PART_BYTES + 61, 97); body.write("0000ftypisom",0);
  const manifest = input(body);
  const started = await service.startVideoUpload(owner, manifest);
  const replay = await service.startVideoUpload(owner, manifest);
  assert.equal(started.id, replay.id); assert.equal(s3.uploads.size,1);
  await expectCode(service.startVideoUpload(owner, {...manifest, checksums: manifest.checksums.map(() => checksum(Buffer.from("wrong")))}),409);
  const beforeForeign = s3.requests.length;
  await expectCode(service.getVideoUpload(other,started.id),404);
  await expectCode(service.signVideoUploadPart(other,started.id,1),404);
  await expectCode(service.completeVideoUpload(other,started.id),404);
  await expectCode(service.abortVideoUpload(other,started.id),404);
  assert.equal(s3.requests.length,beforeForeign);
  assert.throws(() => validateVideoManifest(body.length,["not-a-checksum"]));
  pass("stable ownership and idempotent admission reject foreign users and changed manifests before S3");

  const signed = await service.signVideoUploadPart(owner, started.id, 1);
  const signedHeaders = new URL(signed.uploadUrl).searchParams.get("X-Amz-SignedHeaders")!.split(";");
  assert.ok(signedHeaders.includes("content-length") && signedHeaders.includes("x-amz-checksum-sha256"));
  assert.equal(Object.hasOwn(signed.headers,"content-length"),false,"browser sets the exact Blob length, not forbidden JavaScript headers");
  const part = body.subarray(0,VIDEO_PART_BYTES);
  for (const mutation of [
    { url: signed.uploadUrl, data: body, headers: signed.headers },
    { url: signed.uploadUrl, data: part, headers: {...signed.headers,"x-amz-checksum-sha256":checksum(Buffer.from("bad"))} },
    { url: signed.uploadUrl.replace(/partNumber=1/,"partNumber=2"), data: part, headers: signed.headers },
  ]) {
    const rejected = await fetch(mutation.url,{method:"PUT",headers:mutation.headers,body:new Uint8Array(mutation.data)});
    assert.equal(rejected.status,403); await rejected.body?.cancel();
  }
  const wrongBytes = await fetch(signed.uploadUrl,{method:"PUT",headers:signed.headers,body:new Uint8Array(Buffer.alloc(part.length,98))});
  assert.equal(wrongBytes.status,400); await wrongBytes.body?.cancel();
  assert.equal([...s3.uploads.values()][0].parts.size,0);
  pass("independently verified SigV4 rejects excess size, altered checksum, part-number tampering and incorrect bytes");

  const reusable = await put(owner,started.id,1,part);
  assert.deepEqual((await service.getVideoUpload(owner,started.id)).completedParts,[1]);
  await expectCode(service.completeVideoUpload(owner,started.id),409);
  s3.faults.truncateParts = true; await assert.rejects(service.getVideoUpload(owner,started.id),/fixed part budget/); s3.faults.truncateParts=false;
  const storedFirst = [...s3.uploads.values()][0].parts.get(1).body;
  await put(owner,started.id,2,body.subarray(VIDEO_PART_BYTES));
  assert.deepEqual(storedFirst,part);
  s3.faults.loseCompleteResponse = true;
  const completed = await service.completeVideoUpload(owner,started.id);
  assert.equal(completed.status,"uploaded"); assert.deepEqual(s3.objects.get(started.objectKey).body,body);
  assert.equal((await service.completeVideoUpload(owner,started.id)).status,"uploaded");
  const late = await fetch(reusable.uploadUrl,{method:"PUT",headers:reusable.headers,body:new Uint8Array(part)});
  assert.equal(late.status,404); await late.body?.cancel();
  assert.deepEqual(s3.objects.get(started.objectKey).body,body);
  pass("stored parts resume without re-upload and incomplete or truncated manifests cannot publish; lost completion replies recover safely");

  await db.update(videoUploadSessions).set({status:"uploading"}).where(eq(videoUploadSessions.id,started.id));
  assert.equal((await service.getVideoUpload(owner,started.id)).status,"uploaded");
  await expectCode(db.transaction(tx => service.lockVideoUploadReceiptTx(tx,owner,started.id,{...manifest,objectKey:started.objectKey,sizeBytes:1})),403);
  await db.transaction(async tx => { await service.lockVideoUploadReceiptTx(tx,owner,started.id,{...manifest,objectKey:started.objectKey}); await service.finalizeVideoUploadReceiptTx(tx,started.id,123456); });
  await expectCode(service.abortVideoUpload(owner,started.id),409);
  await expectCode(service.signVideoUploadPart(owner,started.id,1),409);
  pass("a lost database acknowledgement recovers from checksum and session metadata; finalized receipts cannot be cancelled or rewritten");

  const small = Buffer.from("synthetic second upload"), second = await service.startVideoUpload(owner,input(small));
  await put(owner,second.id,1,small); await service.completeVideoUpload(owner,second.id);
  s3.objects.get(second.objectKey).sessionId=randomUUID();
  await db.update(videoUploadSessions).set({status:"uploading"}).where(eq(videoUploadSessions.id,second.id));
  await expectCode(service.getVideoUpload(owner,second.id),422);
  await service.abortVideoUpload(owner,second.id); await service.abortVideoUpload(owner,second.id);
  const jobs = await db.select().from(storageCleanupJobs).where(eq(storageCleanupJobs.objectKey,second.objectKey)); assert.equal(jobs.length,1);
  assert.equal(s3.objects.has(second.objectKey),true,"abort stores intent before cleanup");
  const result = await runStorageCleanupBatch({ids:jobs.map(job=>job.id)}); assert.equal(result.failed,0); assert.equal(result.processed,1);
  assert.equal(s3.objects.has(second.objectKey),false);
  pass("wrong session metadata blocks recovery; cancelling an unfinalized completed object enqueues one durable cleanup intent");

  const outcomes = await Promise.allSettled(Array.from({length:5},()=>service.startVideoUpload(other,input(small))));
  const admitted = outcomes.filter((r):r is PromiseFulfilledResult<Awaited<ReturnType<typeof service.startVideoUpload>>>=>r.status==="fulfilled").map(r=>r.value);
  assert.equal(admitted.length,3); for(const r of outcomes) if(r.status==="rejected") assert.equal(r.reason.status,429);
  const active = admitted[0]; await put(other,active.id,1,small);
  await db.update(videoUploadSessions).set({expiresAt:new Date(Date.now()-1000)}).where(eq(videoUploadSessions.id,active.id));
  await expectCode(service.getVideoUpload(other,active.id),410); await expectCode(service.signVideoUploadPart(other,active.id,1),410);
  assert.equal(await service.expireVideoUploads(),1);
  const [expiredJob] = await db.select().from(storageCleanupJobs).where(eq(storageCleanupJobs.objectKey,active.objectKey));
  assert.equal((await runStorageCleanupBatch({ids:[expiredJob.id]})).failed,0);
  assert.equal([...s3.uploads.values()].some(value=>value.key===active.objectKey),false);
  await db.transaction(tx=>service.retireOwnerVideoUploadsTx(tx,other));
  assert.equal((await db.select().from(videoUploadSessions).where(eq(videoUploadSessions.userId,other))).length,0);
  const remainder = await db.select().from(storageCleanupJobs).where(inArray(storageCleanupJobs.objectKey,admitted.map(r=>r.objectKey)));
  await runStorageCleanupBatch({ids:remainder.map(row=>row.id)});
  assert.equal(s3.uploads.size,0);
  pass("five concurrent initiations admit only three; expired and deleted-owner sessions revoke parts and recover cleanup");

  const legacyKey=`private/video-source/${prefix}/legacy.mp4`;
  const legacyUrl=await transport.createDirectUploadUrl(legacyKey,"video/mp4",small.length);
  const legacyHeaders={"content-type":"video/mp4","if-none-match":"*"};
  const first=await fetch(legacyUrl,{method:"PUT",headers:legacyHeaders,body:new Uint8Array(small)}); assert.equal(first.status,200);await first.body?.cancel();
  const secondPut=await fetch(legacyUrl,{method:"PUT",headers:legacyHeaders,body:new Uint8Array(small)});assert.equal(secondPut.status,412);await secondPut.body?.cancel();
  const noCondition=await fetch(legacyUrl,{method:"PUT",headers:{"content-type":"video/mp4"},body:new Uint8Array(small)});assert.equal(noCondition.status,403);await noCondition.body?.cancel();
  assert.deepEqual(s3.objects.get(legacyKey).body,small);
  pass("legacy single-PUT fallback binds length and If-None-Match, refusing replay overwrite and missing signed constraints");
  const {ensureVideoProcessingTx}=await import("../lib/video-processing");
  const [asset]=await db.insert(videoAssets).values({courseSlug:prefix,lessonId:"atomic-intent",objectKey:`qa/${prefix}/atomic.mp4`,contentType:"video/mp4",sizeBytes:64,status:"ready"}).returning();
  try {
    const capability={available:true,ffmpegPath:"synthetic",ffprobePath:"synthetic",message:"synthetic"};
    await assert.rejects(db.transaction(async tx=>{await ensureVideoProcessingTx(tx,asset.id,capability);throw new Error("rollback-intent");}),/rollback-intent/);
    assert.equal((await db.select().from(videoProcessingJobs).where(eq(videoProcessingJobs.assetId,asset.id))).length,0);
    await db.transaction(tx=>ensureVideoProcessingTx(tx,asset.id,capability));
    await db.update(videoProcessingJobs).set({status:"processing",attempts:2,lockedBy:"synthetic-worker"}).where(eq(videoProcessingJobs.assetId,asset.id));
    const prior=await db.select().from(videoProcessingJobs).where(eq(videoProcessingJobs.assetId,asset.id));
    await db.transaction(tx=>ensureVideoProcessingTx(tx,asset.id,capability));
    assert.deepEqual(await db.select().from(videoProcessingJobs).where(eq(videoProcessingJobs.assetId,asset.id)),prior);
    pass("initial video-processing intent commits with the asset and an idempotent finalize retry never resets an active worker");
  } finally {await db.delete(videoAssets).where(eq(videoAssets.id,asset.id));}
  const report={passed:checks.length,checks,cloudProvider:"loopback HTTP protocol double; no live S3 tested",database:"dedicated PostgreSQL",signedConstraints:"independent SigV4 verification with actual SDK requests"};
  writeFileSync(".data/qa-resumable-video-report.json",JSON.stringify(report,null,2)); console.log(JSON.stringify(report));
} finally {
  if(owners.length) { const sessions=await db.select({key:videoUploadSessions.objectKey}).from(videoUploadSessions).where(inArray(videoUploadSessions.userId,owners));
    const keys=[...sessions.map(s=>s.key),...[...s3.requests].map(r=>decodeURIComponent(r.path.slice(s3.bucket.length+2)))].filter(key=>key.includes(prefix));
    if(keys.length) await db.delete(storageCleanupJobs).where(inArray(storageCleanupJobs.objectKey,keys));
    await db.delete(videoUploadSessions).where(inArray(videoUploadSessions.userId,owners));await db.delete(users).where(inArray(users.id,owners)); }
  assert.equal((await getPool().query("SELECT 1")).rows.length,1);await closeDb();globalThis.fetch=originalFetch;await s3.close();
}
